// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 2, 1e24);
        vm.assume(amount % 2 == 0); // keep b/2 integral so half stays exactly b/2

        // fund the contract directly to `amount`
        vm.deal(address(c), amount);
        // owner is the deployer (this test contract); give it ETH so the transfer succeeds
        vm.deal(address(this), 1 ether);

        c.withdrawAll();

        // General rule: after withdrawAll the contract retains strictly less than
        // half of its prior balance (reference: zero). The mutant keeps exactly
        // amount/2, so amount/2 < amount/2 is false for it.
        assertTrue(address(c).balance < amount / 2);
    }
}
